/**
 * 棋盘形状编码：可见 token 原样（'(' ')' '='），隐藏槽位用 '.'。
 * 这就是玩家在棋盘上看到的东西（括号直接显示、槽位是下划线或灰框）。
 * @param {{hidden:boolean,symbol:string}[]} tokens
 */
export function shapeOfBoard(tokens) {
  return tokens.map((t) => (t.hidden ? '.' : t.symbol)).join('');
}

/**
 * 查某个难度下该形状每个槽位真实可能的类别。
 * @returns {string[]|null} 与槽位序号对齐的类别串数组（如 ['d','o','d']）；未收录返回 null（调用方回退语法 DP）
 */
export function lookupKinds(difficulty, shape) {
  const t = BOARD_KINDS[difficulty];
  if (!t) return null;
  const v = t[shape];
  return v === undefined ? null : v.split(',');
}
